entries.promptTemplate:
{
  "type": "国潮风饮料瓶标签设计",
  "goal": "生成一张可作为产品发布 / 电商主图的饮料瓶 + 标签视觉",
  "brand": {
    "name": "{argument name=\"brand name\" default=\"东风茶事\"}",
    "positioning": "{argument name=\"positioning\" default=\"国潮 + 现代\"}",
    "product_name": "{argument name=\"product name\" default=\"清晨乌龙\"}",
    "product_subtitle": "{argument name=\"product subtitle\" default=\"OOLONG MORNING\"}",
    "volume": "{argument name=\"volume\" default=\"330ml\"}"
  },
  "bottle": {
    "form": "{argument name=\"bottle form\" default=\"短粗玻璃瓶 + 金属盖\"}",
    "material": "{argument name=\"material\" default=\"透明玻璃 + 茶汤可见\"}"
  },
  "label_design": {
    "style": "{argument name=\"label style\" default=\"水墨 + 工笔 + 留白\"}",
    "primary_color": "{argument name=\"primary color\" default=\"墨绿 + 金\"}",
    "background_color": "{argument name=\"label bg\" default=\"米白\"}",
    "illustration": "{argument name=\"illustration\" default=\"工笔 茶山 + 远山\"}",
    "typography": "{argument name=\"typography\" default=\"标题宋体 + 英文 sans\"}",
    "info_strip_bottom": "营养成分 + 容量 + 配料表（小字）"
  },
  "scene": {
    "background": "{argument name=\"background\" default=\"竹席 + 茶碗 + 一片绿叶\"}",
    "lighting": "{argument name=\"lighting\" default=\"自然柔光\"}"
  },
  "format": {
    "aspect_ratio": "{argument name=\"aspect ratio\" default=\"4:5\"}",
    "composition": "瓶身居中 + 微微倾斜 + 标签清晰朝镜头"
  },
  "constraints": {
    "must_keep": [
      "标签风格统一（不混搭水墨 + 美漫）",
      "标签字体 ≤ 2 种",
      "营养标 / 配料表小字可读但不喧宾夺主",
      "瓶身材质真实"
    ],
    "avoid": [
      "标签设计过满",
      "插画风格与文字风格冲突",
      "底色过亮压过插画",
      "出现错别字"
    ]
  }
}

{
  "type": "品牌识别系统板",
  "goal": "生成一张可作为 VI summary / brand board 的品牌识别系统单页",
  "brand": {
    "name": "{argument name=\"brand name\" default=\"AURORA\"}",
    "tagline": "{argument name=\"tagline\" default=\"光，让生活柔软\"}",
    "industry": "{argument name=\"industry\" default=\"家居灯光\"}",
    "personality": "{argument name=\"personality\" default=\"温柔、现代、克制\"}"
  },
  "regions": {
    "logo": {
      "position": "{argument name=\"logo position\" default=\"左上大区\"}",
      "primary_logo": "{argument name=\"primary logo\" default=\"AURORA 字标 + 圆形光晕图形\"}",
      "secondary_logos": ["黑白单色版", "图形版（无文字）", "竖排版"],
      "background_test": "深底 / 浅底各展示一次"
    },
    "color_palette": {
      "position": "{argument name=\"color position\" default=\"右上\"}",
      "primary": [
        "{argument name=\"primary color 1\" default=\"#0F4C81 海军蓝\"}",
        "{argument name=\"primary color 2\" default=\"#FFD166 暖金\"}"
      ],
      "secondary": [
        "{argument name=\"secondary color 1\" default=\"#F4F1EA 米白\"}",
        "{argument name=\"secondary color 2\" default=\"#222 深灰\"}"
      ],
      "swatch_design": "色块 + HEX + 中文名"
    },
    "typography": {
      "position": "{argument name=\"type position\" default=\"左下\"}",
      "headline_font": "{argument name=\"headline font\" default=\"现代 serif（如 Playfair Display）\"}",
      "body_font": "{argument name=\"body font\" default=\"中文圆体 + 英文 sans\"}",
      "demo_block": "Aa Bb Cc 1234 + 一句中文 + 一句英文"
    },
    "applications": {
      "position": "{argument name=\"app position\" default=\"右下\"}",
      "mockups": [
        "{argument name=\"mockup 1\" default=\"名片正反面\"}",
        "{argument name=\"mockup 2\" default=\"产品包装盒\"}",
        "{argument name=\"mockup 3\" default=\"app icon + 闪屏\"}"
      ]
    }
  },
  "style": {
    "art_style": "{argument name=\"art style\" default=\"现代极简 brand board，米色背景 + 微纸纹\"}",
    "grid": "细灰色辅助线"
  },
  "aspect_ratio": "{argument name=\"aspect ratio\" default=\"3:4\"}",
  "constraints": {
    "must_keep": [
      "4 个区块边界清晰",
      "logo 区始终居首位",
      "配色板 ≤ 6 色 + HEX 可读",
      "应用 mockup 风格统一"
    ],
    "avoid": [
      "塞太多元素导致每区无呼吸感",
      "字体超过 2 种家族",
      "颜色超过 6 种",
      "缺少 HEX 编号"
    ]
  }
}

{
  "type": "brand identity and merchandise design board",
  "goal": "生成一张以单一动漫角色为核心的完整品牌发布板，可作为角色出道、周年企划、IP 上线宣传图",
  "theme": {
    "color_palette": "{argument name=\"theme color\" default=\"pastel pink\"} and white",
    "motif": "{argument name=\"motif\" default=\"cherry blossoms\"} and pink hearts",
    "vibe": "{argument name=\"vibe\" default=\"sweet, soft, dreamy, idol-debut energy\"}"
  },
  "character": {
    "name": "{argument name=\"character name\" default=\"癒音ちー\"}",
    "subname": "{argument name=\"character subtext\" default=\"ゆおんちー\"}",
    "description": "{argument name=\"character description\" default=\"anime girl with short brown bob hair, pink eyes, wearing a white hoodie, gentle smile\"}",
    "personality": "{argument name=\"personality\" default=\"治愈系，温柔，喜欢甜食\"}"
  },
  "branding": {
    "main_logo": "{argument name=\"main logo text\" default=\"癒音ちー\"}",
    "sub_logo": "{argument name=\"sub logo text\" default=\"ゆおんちー\"}",
    "social_handle": "{argument name=\"social handle\" default=\"@yuonchii\"}"
  },
  "layout": {
    "format": "single large composite board, vertical poster orientation",
    "aspect_ratio": "{argument name=\"aspect ratio\" default=\"3:4 portrait\"}",
    "background": "{argument name=\"background\" default=\"clean white with soft pink gradient corners and tiny doodles\"}",
    "sections": [
      {
        "type": "header banner",
        "position": "top",
        "elements": ["large main logo", "small sub logo beneath", "cherry blossom decorative graphics", "character portrait on the right"]
      },
      {
        "type": "product packaging",
        "position": "middle left",
        "elements": [
          "1 square box with heart-shaped transparent window showing {argument name=\"packaging filling\" default=\"pink heart candies\"} inside",
          "character illustration printed on the box front",
          "2 individual candy / product wrappers placed beside the box",
          "5 scattered {argument name=\"scattered item\" default=\"heart candies\"} around the packaging"
        ]
      },
      {
        "type": "promotional poster",
        "position": "middle right",
        "elements": [
          "character portrait centered",
          "{argument name=\"poster prop\" default=\"heart-shaped candy bowl\"}",
          "main logo at the top",
          "{argument name=\"event tag\" default=\"4.26 NEW OPEN\"} text",
          "social handle text"
        ]
      },
      {
        "type": "horizontal web banner",
        "position": "lower middle",
        "elements": ["main logo on the left", "{argument name=\"motif\" default=\"cherry blossoms\"} graphics filling the middle", "character portrait on the right", "thin tagline below"]
      },
      {
        "type": "social media profile mockup",
        "position": "bottom left",
        "elements": [
          "header / cover image with logo and motif",
          "1 circular profile picture (character close-up)",
          "handle text '{argument name=\"social handle\" default=\"@yuonchii\"}'",
          "1 follow button (filled accent color)",
          "mock bio: 2-3 lines of character introduction"
        ]
      },
      {
        "type": "merchandise collection",
        "position": "bottom right",
        "count": 9,
        "items": [
          "{argument name=\"merch 1\" default=\"1 white t-shirt with logo\"}",
          "{argument name=\"merch 2\" default=\"1 white mug with character\"}",
          "{argument name=\"merch 3\" default=\"4 round pin badges\"}",
          "{argument name=\"merch 4\" default=\"1 acrylic keychain\"}",
          "{argument name=\"merch 5\" default=\"2 candy packets\"}"
        ]
      }
    ]
  },
  "global_style": {
    "rendering": "polished anime-illustration style for the character + photorealistic product mockups for packaging / merchandise + clean editorial layout for SNS / banner",
    "typography": "main logo in cute display font; SNS / body in clean sans-serif; small handwritten accents",
    "consistency": "the same character appearance used in EVERY section without drift",
    "panel_density": "moderate; each section breathes with consistent margin"
  },
  "constraints": {
    "must_keep": [
      "角色形象在所有 section 中完全一致（发型 / 配色 / 表情 base）",
      "logo / SNS handle 拼写统一",
      "每个 section 有清晰边界，不要互相溢出",
      "包装 / 周边看起来像真实物体而非贴图拼贴"
    ],
    "avoid": [
      "在不同 section 中改变角色发色 / 服装 base color",
      "周边商品看起来是同一物件复制（应有材质差异：陶瓷 / 棉布 / 亚克力 / 纸）",
      "把 SNS profile 区做得不像真实社交平台 UI",
      "header logo 字号被周围装饰挤压到难读"
    ]
  }
}

{
  "type": "护肤精华单瓶包装设计",
  "goal": "生成一张可作为产品发布主图 / 包装提案 / 电商主图的化妆品包装视觉",
  "brand": {
    "name": "{argument name=\"brand name\" default=\"LUMEN\"}",
    "positioning": "{argument name=\"positioning\" default=\"科学护肤 + 极简\"}"
  },
  "product": {
    "name": "{argument name=\"product name\" default=\"光子修护精华\"}",
    "subtitle": "{argument name=\"product subtitle\" default=\"PHOTON REPAIR SERUM\"}",
    "volume": "{argument name=\"volume\" default=\"30ml\"}",
    "form": "{argument name=\"bottle form\" default=\"圆柱形玻璃瓶 + 滴管\"}",
    "key_ingredient": "{argument name=\"ingredient\" default=\"5% 烟酰胺\"}"
  },
  "design": {
    "bottle_material": "{argument name=\"bottle material\" default=\"磨砂透明玻璃\"}",
    "label_material": "{argument name=\"label material\" default=\"哑光不干胶 + 烫银字\"}",
    "primary_color": "{argument name=\"primary color\" default=\"#0F4C81 深蓝\"}",
    "accent_color": "{argument name=\"accent color\" default=\"哑银\"}",
    "typography": "{argument name=\"typography\" default=\"现代 sans + 中文小字号\"}"
  },
  "outer_box": {
    "enabled": "{argument name=\"outer box\" default=\"true\"}",
    "shape": "{argument name=\"box shape\" default=\"立方体硬纸盒\"}",
    "finish": "{argument name=\"box finish\" default=\"哑光纸 + 烫银 logo\"}"
  },
  "scene": {
    "background": "{argument name=\"background\" default=\"米白色丝绸 + 柔光\"}",
    "props": "{argument name=\"props\" default=\"一片透明亚克力板 + 几滴水珠\"}",
    "lighting": "{argument name=\"lighting\" default=\"高级感软光 + 顶部主光\"}"
  },
  "format": {
    "aspect_ratio": "{argument name=\"aspect ratio\" default=\"4:5\"}",
    "composition": "瓶子主体居中偏右 + 外盒在后侧"
  },
  "constraints": {
    "must_keep": [
      "瓶身材质质感真实（玻璃应有反光与折射）",
      "标签字体清晰可读",
      "整体配色 ≤ 3 种",
      "高级感、克制"
    ],
    "avoid": [
      "标签字体 > 2 种",
      "背景过亮压过产品",
      "瓶身比例失真",
      "出现廉价塑料感（如果不是有意）"
    ]
  }
}

{
  "type": "18-panel brand identity and character design document",
  "goal": "生成一张完整记录吉祥物从 DNA 分析到落地应用全流程的设计文档大图，可作为 brand book 一图概览或设计提案 hero 图",
  "brand": {
    "name": "{argument name=\"brand name\" default=\"沐阳 MUYANG TEA\"}",
    "industry": "{argument name=\"industry\" default=\"tea shop\"}",
    "tagline": "{argument name=\"tagline\" default=\"温暖一杯,陪你慢慢喝\"}",
    "colors": [
      "{argument name=\"primary color\" default=\"yellow\"}",
      "{argument name=\"secondary color\" default=\"green\"}",
      "white",
      "brown",
      "dark green"
    ]
  },
  "character": {
    "description": "{argument name=\"character description\" default=\"3D rendered cute Shiba Inu mascot wearing a green apron, big sparkly eyes, plush soft body, friendly smile\"}",
    "rendering_style": "{argument name=\"render style\" default=\"Pixar-quality 3D, soft subsurface scattering, glossy plush texture\"}"
  },
  "layout": {
    "grid": "3 columns by 6 rows",
    "panel_count": 18,
    "panel_borders": "thin light-gray dividers, generous white margin between cells",
    "global_typography": "section titles in bilingual Chinese + English, small body text, panel numbers 01-18 prominently labeled",
    "background": "{argument name=\"page background\" default=\"clean off-white paper\"}"
  },
  "sections": [
    {
      "id": "01",
      "title": "01 品牌DNA分析 / BRAND DNA ANALYSIS",
      "elements": ["small logo lockup", "5 color swatches with HEX codes", "6 brand keyword icons", "small target audience donut chart"]
    },
    {
      "id": "02",
      "title": "02 概念构思 / CONCEPT MOODBOARD",
      "elements": ["5 inspiration photo references", "4 mood / vibe icons", "1 design equation diagram (e.g. 茶 + 狗 + 温暖 = MUYANG)"]
    },
    {
      "id": "03",
      "title": "03 形态研究 / FORM STUDY",
      "elements": ["4 logo anatomy icons", "4 evolution steps from primitive shape to refined silhouette", "4 final silhouette variants"]
    },
    {
      "id": "04",
      "title": "04 概念探索 / CONCEPT EXPLORATION",
      "elements": ["12 quick line-art character sketches with subtle pose / expression variation"]
    },
    {
      "id": "05",
      "title": "05 精细线稿 / REFINED LINE ART",
      "elements": ["3 rows showing front and side line-art with proportion guides, head-body ratio markers, and grid alignment"]
    },
    {
      "id": "06",
      "title": "06 细节精修 / DETAIL REFINEMENT",
      "elements": ["2 large full-body 3D renders with annotation labels", "4 circular close-up callouts (eyes, paw, apron stitch, tail)"]
    },
    {
      "id": "07",
      "title": "07 表情设定 / EXPRESSION SHEET",
      "elements": ["11 3D rendered head expressions: happy, sad, surprised, sleepy, angry, shy, proud, worried, laughing, wink, neutral"]
    },
    {
      "id": "08",
      "title": "08 姿势库 / POSE LIBRARY",
      "elements": ["9 full-body 3D rendered poses: waving, bowing, holding tea, jumping, sitting, sleeping, presenting, running, hugging cup"]
    },
    {
      "id": "09",
      "title": "09 转身视图 / TURNAROUND VIEW",
      "elements": ["5 full-body 3D renders at 0°/45°/90°/135°/180°", "5 matching line-art turnaround views below"]
    },
    {
      "id": "10",
      "title": "10 色彩开发 / COLOR DEVELOPMENT",
      "elements": ["5 rows of 5-color palettes (primary, accent, monochrome, seasonal, dark mode)", "short color psychology paragraph"]
    },
    {
      "id": "11",
      "title": "11 材质规格 / MATERIAL SPECIFICATION",
      "elements": ["5 texture swatches (plush, vinyl, ceramic, fabric, plastic)", "property sliders (softness / glossiness / transparency)", "4 manufacturing process icons"]
    },
    {
      "id": "12",
      "title": "12 色彩应用 / COLOR APPLICATION",
      "elements": ["4 mascot color variant renders", "2 light-mode and dark-mode renders", "4 contrast rating circles (AAA / AA / A / fail)"]
    },
    {
      "id": "13",
      "title": "13 构造指南 / CONSTRUCTION GUIDE",
      "elements": ["1 line-art geometry construction diagram (with circles / triangles / proportion lines)", "1 grid alignment diagram"]
    },
    {
      "id": "14",
      "title": "14 设计系统规则 / DESIGN SYSTEM RULES",
      "elements": ["minimum size icons (16px / 24px / 48px)", "clear-space diagram with X-height markers", "4 do/don't usage examples"]
    },
    {
      "id": "15",
      "title": "15 资产变体 / ASSET VARIANTS",
      "elements": ["3 size variants (S / M / L)", "3 line-art variants", "3 simplified flat icon-style heads"]
    },
    {
      "id": "16",
      "title": "16 数字应用 / DIGITAL APPLICATIONS",
      "elements": ["1 app icon mockup", "2 social avatar mockups", "small UI element row (button / loader / badge)", "3-step animation cycle thumbnails"]
    },
    {
      "id": "17",
      "title": "17 实物应用 / PHYSICAL APPLICATIONS",
      "elements": ["1 plush toy mockup", "1 product packaging mockup", "1 merchandise (tote / mug) mockup", "1 storefront / signage mockup"]
    },
    {
      "id": "18",
      "title": "18 最终主视觉 / FINAL RENDERING",
      "elements": ["1 large hero-size 3D render of mascot in signature pose holding brand product", "logo lockup", "file format / deliverable list"]
    }
  ],
  "global_style": {
    "rendering": "premium design agency presentation board, mixing 3D character renders, line art, photo mockups, charts, and infographic typography",
    "color_tone": "calm, professional, off-white background with brand colors as accents",
    "panel_density": "each panel completely filled but not cluttered; consistent label position (top-left) and small body text",
    "aspect_ratio": "{argument name=\"aspect ratio\" default=\"3:4 portrait poster (e.g. A2 print)\"}"
  },
  "constraints": {
    "must_keep": [
      "18 个模块编号清晰、双语标题",
      "吉祥物造型在所有 3D 模块中保持完全一致",
      "整体像 brand book 一页拼合，而不是 18 张独立海报",
      "每个模块的子元素数量精确（11 表情 / 9 姿势 / 5 转身 / 等）"
    ],
    "avoid": [
      "模块间风格漂移（一个模块 3D 写实、另一个忽然手绘）",
      "省略编号或双语标题",
      "把表情 / 姿势 / 转身画成同一姿势复制",
      "应用 mockup 不像真实物体（如 plush 看起来像截图）"
    ]
  }
}

{
  "type": "吉祥物品牌识别套装",
  "goal": "生成一张可作为吉祥物 brand kit / 周边介绍页的多面板视觉文档",
  "ip": {
    "name": "{argument name=\"ip name\" default=\"AURORA 小光\"}",
    "tagline": "{argument name=\"tagline\" default=\"陪你度过每个夜晚\"}",
    "personality": "{argument name=\"personality\" default=\"温柔、好奇、爱发光\"}",
    "brand_owner": "{argument name=\"brand owner\" default=\"AURORA 家居灯光\"}"
  },
  "mascot": {
    "form": "{argument name=\"mascot form\" default=\"小型半透明灯泡精灵，圆乎乎，有发光的尾巴\"}",
    "color_palette": "{argument name=\"color palette\" default=\"暖金 + 米白 + 浅蓝\"}",
    "rendering": "{argument name=\"rendering\" default=\"3D Pixar 风 + Q 萌\"}"
  },
  "regions": {
    "hero": {
      "position": "{argument name=\"hero position\" default=\"左上大区\"}",
      "content": "吉祥物主形象 + 名字 + 一句性格描述",
      "background": "纯色 + 微光晕"
    },
    "three_view": {
      "position": "{argument name=\"three view position\" default=\"右上\"}",
      "content": "正面 / 侧面 / 背面三视图",
      "label": "FRONT / SIDE / BACK"
    },
    "expressions": {
      "position": "{argument name=\"expression position\" default=\"左下\"}",
      "count": "{argument name=\"expression count\" default=\"6\"}",
      "items": ["开心", "好奇", "困了", "惊讶", "害羞", "小生气"]
    },
    "applications": {
      "position": "{argument name=\"app position\" default=\"右下\"}",
      "items": [
        "{argument name=\"app 1\" default=\"产品包装盒角落\"}",
        "{argument name=\"app 2\" default=\"app 启动页\"}",
        "{argument name=\"app 3\" default=\"周边贴纸\"}",
        "{argument name=\"app 4\" default=\"短视频片头吉祥物动画静帧\"}"
      ]
    }
  },
  "style": {
    "background": "{argument name=\"background\" default=\"米色纸纹 + 细灰辅助线\"}",
    "typography": "圆润 sans + 一行手写体强调"
  },
  "aspect_ratio": "{argument name=\"aspect ratio\" default=\"3:4\"}",
  "constraints": {
    "must_keep": [
      "吉祥物在所有区块外观一致",
      "三视图比例严格统一",
      "表情清晰可识别",
      "应用场景符合品牌"
    ],
    "avoid": [
      "吉祥物在不同区块画风漂移",
      "表情夸张到失真",
      "配色出现强烈对比破坏 IP 调性",
      "应用 mockup 风格冲突"
    ]
  }
}

{
  "type": "动漫立项 Pitch Board",
  "goal": "生成一张可作为动漫 / 游戏立项 pitch 的全套视觉文档单页",
  "ip": {
    "title": "{argument name=\"title\" default=\"霜白幻想曲\"}",
    "title_localized": "{argument name=\"title localized\" default=\"FROZEN FANTASIA\"}",
    "tagline": "{argument name=\"tagline\" default=\"这场雪，下了一千年\"}",
    "logline": "{argument name=\"logline\" default=\"在永恒冬季的王国里，一个忘记自己名字的少女遇到一只能听懂雪的狐狸，他们决定一起寻找春天的源头\"}",
    "genre": "{argument name=\"genre\" default=\"奇幻 / 治愈 / 冒险\"}"
  },
  "regions": {
    "main_kv": {
      "position": "{argument name=\"kv position\" default=\"上半部分占 60%\"}",
      "content": "{argument name=\"kv content\" default=\"少女主角站在雪原中，背景为冰封城堡，狐狸在脚边\"}",
      "style": "电影海报级 anime 厚涂"
    },
    "character_cards": {
